def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    marker = next(v for v in colors if v not in (0, bg))
    out = [row[:] for row in grid]

    # Spread the marker into zero cells which are adjacent to marker cells,
    # repeating the local growth step several times.
    frontier = {(r, c) for r in range(h) for c in range(w)
                if grid[r][c] == marker}
    for _ in range(max(h, w)):
        new = set()
        for r, c in frontier:
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                y, x = r + dr, c + dc
                if 0 <= y < h and 0 <= x < w and out[y][x] == 0:
                    out[y][x] = marker
                    new.add((y, x))
        frontier = new
        if not frontier:
            break
    return out
